    /**
     * Lazily initializes and returns the county data map.
     *
     * @return array<string, array{fullName: string, fipsCode: array, parent: string}>
     */
    private static function countyData(): array
    {
        // ---
        // Define arrow function to extract county data from CountyInfo
        // attributes into an associative array
        // ---
        $dataExtractor = fn ($info, $caseValue) => [
            'fullName' => $info->fullName,
            'fipsCode' => $info->fipsCode,
            'parent' => $info->parent,
        ];

        // ---
        // Build and cache the lazy data map using reflection to extract
        // CountyInfo attributes from all enum cases
        // ---
        $result = EnumDataUtils::buildLazyDataMap(
            self::class,
            CountyInfo::class,
            $dataExtractor
        );

        // Clean up variables to free up memory
        unset(
            $dataExtractor
        );

        // Return the cached county data map
        return $result;
    }

    /**
     * Get the full name of the county.
     *
     * @return string The full name
     */
    public function fullName(): string
    {
        // Resolve from cached county data
        $data = self::countyData();

        // Throw if county is not found
        return EnumDataUtils::getFieldValue(
            $data,
            $this->value,
            'fullName',
            'county'
        );
    }

    /**
     * Get the FIPS county code.
     *
     * @return string The FIPS county code (5-digit string)
     */
    public function fipsCode(): string
    {
        // Resolve from cached county data
        $data = self::countyData();

        // Return the three-digit county FIPS, or null if missing
        return EnumDataUtils::getFieldValue(
            $data,
            $this->value,
            'fipsCode',
            'county'
        );
    }

    /**
     * Get the parent state, territory, or district.
     *
     * @return ?string The parent state, territory, or district
     */
    public function parent(): ?string
    {
        // Resolve from cached county data
        $data = self::countyData();

        // Return the USPS state code for the parent, or null if missing
        return EnumDataUtils::getFieldValue(
            $data,
            $this->value,
            'parent',
            'county'
        );
    }
